func writeClaudeSettingsFile(cfg *agent.HookConfigFile, rawSettings, rawHooks, rawPermissions map[string]json.RawMessage) error {
	hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
	if err != nil {
		return fmt.Errorf("failed to marshal hooks: %w", err)
	}
	rawSettings["hooks"] = hooksJSON

	// An emptied permissions block is deleted, not written back as {}. Removing
	// the retired deny rule can empty it, and leaving "permissions": {} behind
	// in a tracked settings file is noise Entire put there. UninstallHooks and
	// agent.RepairRetiredMetadataDenyRule both do the same.
	if len(rawPermissions) == 0 {
		delete(rawSettings, "permissions")
	} else {
		permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
		if err != nil {
			return fmt.Errorf("failed to marshal permissions: %w", err)
		}
		rawSettings["permissions"] = permJSON
	}

	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal settings: %w", err)
	}

	// Write creates .claude with MkdirAllNoSymlink, so a checked-in symlink
	// there is refused by name rather than followed.
	return cfg.Write(output, 0o600) //nolint:wrapcheck // agent.HookConfigFile already names the file in its error
}

3. cmd/entire/cli/agent/hook_config_file.go:152-172 HookConfigFile.Write s=40.1 [focus:152]
func (f *HookConfigFile) Write(data []byte, perm os.FileMode) error {
	if dir := path.Dir(f.name); dir != "." {
		// 0750 for every agent, including the directories Entire creates below
		// an agent's own (.pi/extensions/entire). The agent process runs as
		// whoever ran `entire enable`, so it can traverse its own config
		// directory; a setup where those differ (provisioned as root, agent as
		// another uid) needs 0755 for all nine and is not one agent's to choose.
		if err := osroot.MkdirAllNoSymlink(f.root, dir, 0o750); err != nil {
			return fmt.Errorf("create %s: %w", filepath.Dir(f.path), err)
		}
	}
	if info, err := osroot.LstatNoSymlinks(f.root, f.name); err == nil && info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("write %s: %w", f.path, osroot.ErrSymlinkedPath)
	} else if err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("write %s: %w", f.path, err)
	}
	if err := jsonutil.WriteFileAtomicIn(f.root, f.name, data, perm); err != nil {
		return fmt.Errorf("write %s: %w", f.path, err)
	}
	return nil
}

4. cmd/entire/cli/status.go:200-278 formatSettingsStatusShort s=38.7 [focus:200]
func formatSettingsStatusShort(ctx context.Context, s *EntireSettings, sty statusStyles) string {
	var b strings.Builder

	if s.Enabled {
		b.WriteString(sty.render(sty.green, "●"))
		b.WriteString(" ")
		b.WriteString(sty.render(sty.bold, "Enabled"))
	} else {
		b.WriteString(sty.render(sty.red, "○"))
		b.WriteString(" ")
		b.WriteString(sty.render(sty.bold, "Disabled"))
	}

	// Resolve branch from repo root
	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
		if branch := resolveWorktreeBranch(ctx, repoRoot); branch != "" {
			b.WriteString(sty.render(sty.dim, " · "))
			b.WriteString("branch ")
			b.WriteString(sty.render(sty.cyan, branch))
		}
	}

	// Show enabled agents
	if s.Enabled {
		if displayNames := InstalledAgentDisplayNames(ctx); len(displayNames) > 0 {
			b.WriteString("\n")
			b.WriteString(sty.render(sty.dim, "  Agents · "))

			b.WriteString(strings.Join(displayNames, ", "))
		}

		// Warn when installed hooks are out of date (read-only; fix is manual).
		for _, name := range OutdatedHookAgents(ctx) {
			ag, err := agent.Get(name)
			if err != nil {
				continue
			}
