func TestResolveWorktreeBranch_RegularRepo(t *testing.T) {
	dir := t.TempDir()
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		dir = resolved
	}

	testutil.InitRepo(t, dir)

