 79		// plain `entire enable` must drop the retired metadata deny rule, not just
 80		// --force. See agent.MetadataDenyRule for why it is retired. Removing it is
 81		// the whole reason a normal enable still touches permissions.
 82		permissionsChanged, err := agent.RemoveMetadataDenyRule(rawPermissions)
 83		if err != nil {
 84			return 0, fmt.Errorf("failed to update permissions in %s: %w", cfg.Path(), err)
 85		}
