165	// installHookEntries mutates rawHooks in place to ensure every Entire hook is
166	// present, migrating stale entries (from older CLI versions or, when force is
167	// set, any current Entire hook) first. Returns the number of hooks newly
168	// added and whether any stale entry was dropped (see the staleDropped comment
169	// at its InstallHooks call site for why that forces a write on its own).
170	func installHookEntries(rawHooks map[string]json.RawMessage, force bool) (count int, staleDropped bool) {
171		var preToolUse, postToolUse []ClaudeHookMatcher
172		parseHookType(rawHooks, "PreToolUse", &preToolUse)
173		parseHookType(rawHooks, "PostToolUse", &postToolUse)
174	
175		// The "simple" hook types all share one shape: a single Entire command
176		// under an empty-string matcher, no tool-use targeting. Handling them
177		// data-driven (rather than one parse/strip/add/marshal block per type)
178		// keeps this function's complexity from growing linearly with each new
179		// simple hook type Entire registers.
180		simpleHooks := []struct {
300		}
301	}
