303	// marshalHookType marshals a hook type back to rawHooks.
304	// If the slice is empty, removes the key from rawHooks.
305	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []ClaudeHookMatcher) {
306		if len(matchers) == 0 {
307			delete(rawHooks, hookType)
308			return
309		}
310		data, err := jsonutil.MarshalWithNoHTMLEscape(matchers)
311		if err != nil {
312			return // Silently ignore marshal errors (shouldn't happen)
313		}
314		rawHooks[hookType] = data
315	}
