317	// UninstallHooks removes Entire hooks from Claude Code settings.
318	func (c *ClaudeCodeAgent) UninstallHooks(ctx context.Context) error {
319		cfg, err := claudeHookConfig(ctx)
320		if err != nil {
321			return err
322		}
323		data, err := cfg.Read()
324		if err != nil {
325			// Same split AreHooksInstalled makes: an absent file is an answer, an
326			// unreadable one is not. Collapsing both to "nothing to uninstall" leaves
327			// the hooks on disk and reports success, which is what uninstall is
328			// supposed to stop doing.
329			if errors.Is(err, os.ErrNotExist) {
330				return nil
331			}
332			return fmt.Errorf("read %s: %w", cfg.Path(), err)
333		}
334	
335		var rawSettings map[string]json.RawMessage
336		if err := json.Unmarshal(data, &rawSettings); err != nil {
337			return fmt.Errorf("failed to parse settings.json: %w", err)
338		}
339	
340		// rawHooks preserves unknown hook types (e.g., "Notification")
341		var rawHooks map[string]json.RawMessage
342		if hooksRaw, ok := rawSettings["hooks"]; ok {
343			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
344				return fmt.Errorf("failed to parse hooks: %w", err)
345			}
346		}
347		if rawHooks == nil {
348			rawHooks = make(map[string]json.RawMessage)
349		}
350	
351		// Parse only the hook types we need to modify
352		var sessionStart, sessionEnd, stop, subagentStop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
353		parseHookType(rawHooks, "SessionStart", &sessionStart)
354		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
355		parseHookType(rawHooks, "Stop", &stop)
356		parseHookType(rawHooks, "SubagentStop", &subagentStop)
357		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
358		parseHookType(rawHooks, "PreToolUse", &preToolUse)
359		parseHookType(rawHooks, "PostToolUse", &postToolUse)
360	
361		// Remove Entire hooks from all hook types
362		sessionStart = removeEntireHooks(sessionStart)
363		sessionEnd = removeEntireHooks(sessionEnd)
364		stop = removeEntireHooks(stop)
365		subagentStop = removeEntireHooks(subagentStop)
366		userPromptSubmit = removeEntireHooks(userPromptSubmit)
367		preToolUse = removeEntireHooksFromMatchers(preToolUse)
368		postToolUse = removeEntireHooksFromMatchers(postToolUse)
369	
370		// Marshal modified hook types back to rawHooks
371		marshalHookType(rawHooks, "SessionStart", sessionStart)
372		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
373		marshalHookType(rawHooks, "Stop", stop)
374		marshalHookType(rawHooks, "SubagentStop", subagentStop)
375		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
376		marshalHookType(rawHooks, "PreToolUse", preToolUse)
377		marshalHookType(rawHooks, "PostToolUse", postToolUse)
378	
379		// Also remove the metadata deny rule from permissions
380		var rawPermissions map[string]json.RawMessage
381		if permRaw, ok := rawSettings["permissions"]; ok {
382			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
383				// If parsing fails, just skip permissions cleanup
384				rawPermissions = nil
385			}
386		}
387	
388		if rawPermissions != nil {
389			// Same removal InstallHooks now performs; a marshal failure here leaves
390			// the rule in place, which uninstall reports through the write below
391			// rather than aborting the rest of the hook removal.
392			_, _ = agent.RemoveMetadataDenyRule(rawPermissions) //nolint:errcheck // best-effort during uninstall; hook removal must still complete
393	
394			// If permissions is empty, remove it entirely
395			if len(rawPermissions) > 0 {
396				permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
397				if err == nil {
398					rawSettings["permissions"] = permJSON
399				}
400			} else {
401				delete(rawSettings, "permissions")
402			}
403		}
404	
405		// Marshal hooks back (preserving unknown hook types)
406		if len(rawHooks) > 0 {
407			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
408			if err != nil {
409				return fmt.Errorf("failed to marshal hooks: %w", err)
410			}
411			rawSettings["hooks"] = hooksJSON
412		} else {
413			delete(rawSettings, "hooks")
414		}
415	
416		// Write back
417		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
418		if err != nil {
419			return fmt.Errorf("failed to marshal settings: %w", err)
420		}
421		return cfg.Write(output, 0o600) //nolint:wrapcheck // agent.HookConfigFile already names the file in its error
422	}
