424	// loadClaudeSettings reads and parses .claude/settings.json from the repo root.
425	// A missing file returns the zero settings and no error — that is the answer
426	// "nothing configured". An unreadable or malformed file returns an error: the
427	// answer could not be read, which is a different thing.
428	func loadClaudeSettings(ctx context.Context) (ClaudeSettings, error) {
429		cfg, err := claudeHookConfig(ctx)
430		if err != nil {
431			return ClaudeSettings{}, err
432		}
433		data, err := cfg.Read()
434		// No settings file means no hooks, which is an answer; anything else means we
435		// could not read the answer.
436		if errors.Is(err, os.ErrNotExist) {
437			return ClaudeSettings{}, nil
438		}
439		if err != nil {
440			logging.Warn(ctx, "claude-code: failed to read settings file", "path", cfg.Path(), "err", err)
441			return ClaudeSettings{}, fmt.Errorf("read %s: %w", cfg.Path(), err)
442		}
443	
444		var settings ClaudeSettings
445		if err := json.Unmarshal(data, &settings); err != nil {
446			logging.Warn(ctx, "claude-code: failed to parse settings file", "path", cfg.Path(), "err", err)
447			return ClaudeSettings{}, fmt.Errorf("parse %s: %w", cfg.Path(), err)
448		}
449		return settings, nil
450	}
