452	// AreHooksInstalled checks if Entire hooks are installed.
453	//
454	// A missing settings file is an answer — no hooks — while an unreadable or
455	// malformed one is an error: "we could not tell" and "there are none" are
456	// different things to a caller deciding whether hooks can be left alone.
457	func (c *ClaudeCodeAgent) AreHooksInstalled(ctx context.Context) (bool, error) {
458		settings, err := loadClaudeSettings(ctx)
459		if err != nil {
460			return false, err
461		}
462		// Check for at least one of our hooks (new, wrapped, or legacy format)
463		return hasEntireHook(settings.Hooks.Stop), nil
464	}
