466	// HookConfigState describes how Entire's Claude Code hooks compare to what
467	// InstallHooks would write today. Aliased to the shared agent-package type so
468	// `entire status` and `entire doctor` can treat every agent's drift check
469	// uniformly; the names stay exported here for existing call sites.
470	//
471	// For Claude Code, HooksOutdated means Entire hooks are installed but the
472	// current tool-use matchers no longer carry them (e.g. an older CLI wrote them
473	// under the now non-firing "Task"/"TodoWrite" matchers).
474	type HookConfigState = agent.HookConfigState
475	
476	const (
477		// HooksAbsent means Entire hooks are not installed in this repo.
478		HooksAbsent = agent.HooksAbsent
479		// HooksCurrent means the installed hooks match the current config.
480		HooksCurrent = agent.HooksCurrent
481		// HooksOutdated means the installed hooks are stale.
482		// Fix: `entire enable --force`.
483		HooksOutdated = agent.HooksOutdated
484	)
