486	// CheckHookConfig satisfies agent.HookFreshness by delegating to the
487	// package-level check, which predates the interface and is still called
488	// directly by tests.
489	func (c *ClaudeCodeAgent) CheckHookConfig(ctx context.Context) agent.HookConfigState {
490		return CheckHookConfig(ctx)
491	}
492	
493	// CheckHookConfig reports whether Entire's Claude Code hooks are absent,
494	// current, or outdated. It is a read-only diagnostic used by `entire status`
495	// and `entire doctor`; it never modifies settings. Outdated is detected on the
496	// positive spec: Entire is installed (Stop hook present) yet one of the current
497	// tool-use matchers does not carry its Entire hook.
498	func CheckHookConfig(ctx context.Context) HookConfigState {
499		settings, err := loadClaudeSettings(ctx)
500		// An unreadable or malformed settings file collapses to HooksAbsent
501		// deliberately. This is a coarse three-state diagnostic for `entire status`
502		// and `entire doctor`, and no caller here acts on "could not tell" —
503		// AreHooksInstalled is the API that propagates that distinction to callers
504		// which must (e.g. uninstall deciding whether hooks can be left alone).
505		// loadClaudeSettings has already logged the failure.
506		if err != nil || !hasEntireHook(settings.Hooks.Stop) {
507			return HooksAbsent
508		}
509		subagentTools := splitMatcherTools(subagentToolMatcher)
510		taskTools := splitMatcherTools(taskToolMatcher)
511		if !hasEntireHookCoveringTools(settings.Hooks.PreToolUse, subagentTools) ||
512			!hasEntireHookCoveringTools(settings.Hooks.PostToolUse, subagentTools) ||
513			!hasEntireHookCoveringTools(settings.Hooks.PostToolUse, taskTools) ||
514			!hasEntireHook(settings.Hooks.SubagentStop) {
515			return HooksOutdated
516		}
517		return HooksCurrent
518	}
