521	
522	func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
523		for _, matcher := range matchers {
524			for _, hook := range matcher.Hooks {
525				if hook.Command == command {
526					return true
527				}
528			}
529		}
530		return false
680		// Same logic as removeEntireHooks - both work on the same structure
681		return removeEntireHooks(matchers)
682	}
