   614			return false
   615		}
   616		return *s.Redaction.Goredact.Enabled
   617	}
   618	
   619	// ErrScannerConfig marks scanner-configuration failures. Consumers use
   620	// errors.Is to distinguish these (fail-closed) from ordinary settings
   621	// problems (warn-and-default).
   622	var ErrScannerConfig = errors.New("invalid redaction scanner configuration")
   623	
   624	// validateScannerSettings enforces the fail-closed rule: at least one secret
   625	// scanner must be enabled. This runs only on merged settings (see
   626	// loadMergedSettings) — never in the per-file loaders — because those loaders
   627	// serve display/inspection consumers reading a single file in isolation
   628	// (entire status via LoadFromFile, investigate via LoadFromBytes), and a
   629	// local file may legally contain scanner keys that are inert even after merge.
   630	func validateScannerSettings(s *EntireSettings) error {
   631		if !s.BetterleaksEnabled() && !s.GoredactEnabled() {
   632			return fmt.Errorf("%w: at least one secret scanner must be enabled; re-enable redaction.betterleaks or enable redaction.goredact", ErrScannerConfig)
   633		}
   634		return nil
   635	}
   636	
   637	// Load loads the Entire settings from .entire/settings.json, then applies
   638	// clone-local preferences from the git common dir, then applies any overrides
   639	// from .entire/settings.local.json if it exists.
   640	// Returns default settings if no settings or preferences file exists.
   641	// Works correctly from any subdirectory within the repository.
   642	func Load(ctx context.Context) (*EntireSettings, error) {
   643		if worktreeRoot, ok := worktreeRootFromContext(ctx); ok {
   644			return loadForWorktreeRoot(ctx, worktreeRoot)
   645		}
   646	
   647		settingsFileAbs, localSettingsFileAbs, err := settingsAbsPaths(ctx)
   648		if err != nil {
   649			return nil, err
   650		}
   651		preferencesFileAbs := ""
   652		if path, prefErr := ClonePreferencesPath(ctx); prefErr == nil {
   653			preferencesFileAbs = path
   654		} else {
   655			// Log at Debug rather than silently dropping the preferences layer.
   656			// "Not in a git repo" is a legitimate case (some commands run outside
   657			// a repo), but a git PATH issue or .git/ permission failure is worth
   658			// finding via `ENTIRE_LOG_LEVEL=debug` when users report "my picker
   659			// choices vanished".
   660			logging.Debug(ctx, "clone preferences path unresolved; skipping preferences layer",
   661				slog.String("error", prefErr.Error()))
   662		}
   663	
   664		return loadMergedSettings(ctx, settingsFileAbs, preferencesFileAbs, localSettingsFileAbs)
   665	}
   666	
   667	// settingsAbsPaths resolves the base and local settings file paths against the
   668	// repository anchor. Resolution failures are returned rather than converted to
   669	// cwd-relative paths: doing the latter can select a different .entire from a
   670	// subdirectory precisely when Git could not establish which repository owns it.
   671	func settingsAbsPaths(ctx context.Context) (base, local string, err error) {
   672		// entiredir.PathTo, not paths.AbsPath: both files live under .entire, and
   673		// entiredir owns the one anchor for that directory. AbsPath's failure mode
   674		// here was a relative path that then resolved against the process's own
   675		// directory, which is the thing the anchor exists to prevent.
   676		base, err = entiredir.PathTo(ctx, EntireSettingsFile)
   677		if err != nil {
   678			return "", "", fmt.Errorf("resolve project settings path: %w", err)
   679		}
   680		local, err = entiredir.PathTo(ctx, EntireSettingsLocalFile)
   681		if err != nil {
   682			return "", "", fmt.Errorf("resolve local settings path: %w", err)
   683		}
   684		return base, local, nil
   685	}
   686	
   687	// worktreeSettingsPaths resolves the base and local settings file paths under
   688	// an explicit worktree root.
   689	func worktreeSettingsPaths(worktreeRoot string) (base, local string) {
   690		return filepath.Join(worktreeRoot, EntireSettingsFile), filepath.Join(worktreeRoot, EntireSettingsLocalFile)
   691	}
   692	
   693	func loadForWorktreeRoot(ctx context.Context, worktreeRoot string) (*EntireSettings, error) {
   694		settingsFileAbs, localSettingsFileAbs := worktreeSettingsPaths(worktreeRoot)
   695		preferencesFileAbs := ""
   696		if path, prefErr := clonePreferencesPathForWorktreeRoot(ctx, worktreeRoot); prefErr == nil {
   697			preferencesFileAbs = path
   698		} else {
   699			logging.Debug(ctx, "clone preferences path unresolved; skipping preferences layer",
   700				slog.String("error", prefErr.Error()))
   701		}
   702		return loadMergedSettings(ctx, settingsFileAbs, preferencesFileAbs, localSettingsFileAbs)
   703	}
   704	
   705	func clonePreferencesPathForWorktreeRoot(ctx context.Context, worktreeRoot string) (string, error) {
   706		cmd := exec.CommandContext(ctx, "git", "-C", worktreeRoot, "rev-parse", "--git-common-dir")
   707		output, err := cmd.Output()
   708		if err != nil {
   709			return "", fmt.Errorf("resolve git common dir: %w", err)
   710		}
   711	
   712		commonDir := strings.TrimSpace(string(output))
   713		if !filepath.IsAbs(commonDir) {
   714			commonDir = filepath.Join(worktreeRoot, commonDir)
   715		}
   716		return filepath.Join(filepath.Clean(commonDir), ClonePreferencesFile), nil
   717	}
   718	
   719	// worktreeRootOfSettingsFile recovers the worktree root a settings path was
   720	// built from: settingsAbsPaths joins <root>/.entire/<file>, so the root is two
   721	// levels up. Used only as the KEY the vouched-symlink policy is scoped by, never
   722	// as a base for I/O, so the derived-path rule in CLAUDE.md does not apply -- an
   723	// inconsistent key costs a refused symlink, which is the safe direction.
   724	func worktreeRootOfSettingsFile(settingsFileAbs string) string {
   725		if settingsFileAbs == "" {
   726			return ""
   727		}
   728		return filepath.Dir(filepath.Dir(settingsFileAbs))
   729	}
   730	
   731	func loadMergedSettings(ctx context.Context, settingsFileAbs, preferencesFileAbs, localSettingsFileAbs string) (*EntireSettings, error) {
   732		// Load base settings
   733		settings, err := loadFromFile(settingsFileAbs)
   734		if err != nil {
   735			return nil, fmt.Errorf("reading settings file: %w", err)
   736		}
   737	
   738		var preferences *ClonePreferences
   739		if preferencesFileAbs != "" {
   740			preferences, err = loadClonePreferencesFromFile(preferencesFileAbs)
   741			if err != nil {
   742				return nil, fmt.Errorf("reading clone preferences file: %w", err)
   743			}
   744			applyClonePreferences(settings, preferences)
   745		}
   746	
   747		// Apply local overrides if they exist — but only from a file that is
   748		// genuinely local. See localLayerTrackedReason.
   749		localData, err := readConfined(localSettingsFileAbs)
   750		if err != nil {
   751			if !errors.Is(err, fs.ErrNotExist) {
   752				return nil, fmt.Errorf("reading local settings file: %w", err)
   753			}
   754			// Local file doesn't exist, continue without overrides
   755		} else if classifyLocalSettings(ctx, localSettingsFileAbs) == localTracked {
   756			// Dropped only on PROOF that the file is tracked. Discarding every
   757			// local setting because a repository could not be read would be a
   758			// worse failure than the one being guarded against — the exec-bearing
   759			// OPF command applies the stricter policy for itself.
   760			settings.localLayerRejection = localLayerTrackedReason
   761			localData = nil
   762		} else if err := mergeJSON(settings, localData); err != nil {
   763			return nil, fmt.Errorf("merging local settings: %w", err)
   764		}
   765	
   766		// openai_privacy_filter.command is executed, so it is honored only from a
   767		// local file positively verified as this developer's own. external_agents
   768		// grants execution of every entire-agent-* binary on $PATH, so it gets the
   769		// same gate. Agent instruction fields (investigate.always_prompt, review
   770		// prompts) are appended verbatim to prompts of agents spawned with
   771		// approval checks disabled, so they get the same provenance requirement,
   772		// with clone-local preferences as an additional trusted layer.
   773		enforceOPFCommandTrust(ctx, settings, localSettingsFileAbs, localData)
   774		enforceExternalAgentsTrust(ctx, settings, localSettingsFileAbs, localData)
   775		enforceAgentPromptTrust(ctx, settings, localSettingsFileAbs, localData, preferences)
   776		// allow_symlinked_agent_dirs decides where Entire writes an agent's hook
   777		// config, so it gets the same gate, and then installs the surviving set as
   778		// the process-wide policy.
   779		enforceSymlinkedAgentDirsTrust(ctx, settings, localSettingsFileAbs, localData)
   780		applyVouchedAgentDirs(settings, worktreeRootOfSettingsFile(settingsFileAbs))
   781	
   782		// Re-validate after merge. Individual files are validated by loadFromFile,
   783		// but mergeJSON patches fields independently and can produce combinations
   784		// (e.g. model without provider when the local override sets only a model
   785		// on top of a base with no provider) that neither file alone contained.
   786		if err := settings.SummaryGeneration.Validate(); err != nil {
   787			return nil, fmt.Errorf("merged settings invalid: %w", err)
   788		}
   789	
   790		if err := validateScannerSettings(settings); err != nil {
   791			return nil, fmt.Errorf("merged settings invalid: %w", err)
   792		}
   793	
   794		return settings, nil
   795	}
   796	
   797	// LoadFromFile loads settings from a specific file path without merging local overrides.
   798	// Returns default settings if the file doesn't exist.
   799	// Use this when you need to display individual settings files separately.
   800	func LoadFromFile(filePath string) (*EntireSettings, error) {
   801		return loadFromFile(filePath)
   802	}
   803	
   804	// LoadProjectRaw reads .entire/settings.json as a generic JSON object so
   805	// callers can inspect or mutate individual keys without losing unrelated
   806	// fields to round-trip decoding.
   807	//
   808	// Returns:
   809	//   - path: absolute path of the project settings file.
   810	//   - raw: parsed JSON object, or an empty map when the file is missing.
   811	//   - exists: false when the file does not exist (raw is empty); true otherwise.
   812	//   - err: parse error or read error other than ENOENT.
   813	//
   814	// Pair with SaveProjectRaw for read-modify-write flows that need to preserve
   815	// unrelated keys. Owning the path resolution and raw IO here keeps callers
   816	// from duplicating settings parsing in violation of the "Settings access must
   817	// go through the settings package" rule in CLAUDE.md.
   818	func LoadProjectRaw(ctx context.Context) (path string, raw map[string]json.RawMessage, exists bool, err error) {
   819		return loadRaw(ctx, EntireSettingsFile, "project")
   820	}

