1030	// statusJSON is the JSON output for `entire status --json`.
1031	type statusJSON struct {
1032		Enabled        bool               `json:"enabled"`
1033		Agents         []string           `json:"agents"`
1034		ActiveSessions []sessionBriefJSON `json:"active_sessions"`
1035		// AgentHelp is the machine-readable pointer for no-channel agents that parse
1036		// `entire status --json` instead of the human footer. Set only on the
1037		// success path (mirrors writeAgentHelpHint, which only renders when set up).
1038		AgentHelp string `json:"agent_help,omitempty"`
1039		// HooksOutdated lists agents whose installed hook config is out of date and
1040		// should be refreshed with `entire enable --force`.
1041		HooksOutdated []string `json:"hooks_outdated,omitempty"`
1042		// CodexHooks reports effective discovery/trust warnings separately from
1043		// current-checkout installation and freshness semantics.
1044		CodexHooks *codexHooksStatusJSON `json:"codex_hooks,omitempty"`
1045		// CheckpointPushDisabled is emitted only when Entire is enabled and the
1046		// effective push_sessions setting is false. Its absence does not guarantee
1047		// that a push can succeed.
1048		//
1049		// No other field is omitted or suppressed when it is set: read it as
1050		// requalifying the fields below rather than removing them.
1051		// CheckpointSyncRemote is then the remote checkpoints are READ from, and
1052		// the error and ignored-remote diagnostics apply to reads as well.
1053		// UnpushedCheckpoints keeps its own meaning either way: checkpoints not
1054		// present on THAT destination, which is not a claim that they exist
1055		// nowhere else.
1056		CheckpointPushDisabled bool `json:"checkpoint_push_disabled,omitempty"`
1057		// CheckpointSyncRemote is the elected checkpoint sync remote name, or the
1058		// org/repo slug in dedicated checkpoint_remote mode. Deliberately not named
1059		// checkpoint_remote, which is the existing GitHub-coupled setting.
1060		CheckpointSyncRemote       string `json:"checkpoint_sync_remote,omitempty"`
1061		CheckpointSyncRemoteSource string `json:"checkpoint_sync_remote_source,omitempty"` // config|observed|default|sole|first|dedicated
1062		CheckpointSyncError        string `json:"checkpoint_sync_error,omitempty"`         // fail-closed message
1063		// CheckpointReadSourceUnknown reports that the read-source probe failed,
1064		// so no read source could be determined. Emitted only alongside
1065		// checkpoint_push_disabled, and checkpoint_sync_remote is then absent
1066		// rather than guessed at.
1067		CheckpointReadSourceUnknown bool `json:"checkpoint_read_source_unknown,omitempty"`
1068		// CheckpointReadFallback is the remote reads fall open to when the
1069		// election failed, so checkpoint_sync_error is set. Emitted only
1070		// alongside checkpoint_push_disabled, and only when the dedicated store
1071		// is not what serves reads — if it is, checkpoint_sync_remote carries it
1072		// (with source "dedicated") even though nothing was elected, and a failed
1073		// probe sets checkpoint_read_source_unknown instead. Absence here does
1074		// not mean reads fall open to nothing.
1075		CheckpointReadFallback string `json:"checkpoint_read_fallback,omitempty"`
1076		UnpushedCheckpoints    int    `json:"unpushed_checkpoints,omitempty"`
1077		// CheckpointRemoteIgnored/-Reason report a configured checkpoint_remote the
1078		// ownership check rejected as inherited with the clone (reads and pushes
1079		// fall back to the elected remote). Mirrors the text path's warning line.
1080		CheckpointRemoteIgnored       string `json:"checkpoint_remote_ignored,omitempty"`
1081		CheckpointRemoteIgnoredReason string `json:"checkpoint_remote_ignored_reason,omitempty"`
1082		// SecretScanners lists the enabled engines when non-default; omitted when default.
1083		SecretScanners []string `json:"secret_scanners,omitempty"`
1084		Error          string   `json:"error,omitempty"`
1085	}
