1155	
1156			result.SecretScanners = nonDefaultSecretScanners(s)
1157	
1158			for _, name := range OutdatedHookAgents(ctx) {
1159				result.HooksOutdated = append(result.HooksOutdated, string(name))
1160			}
1161			result.CodexHooks = codexHooksStatusFromIssue(inspectCodexHookIssue(ctx))
1162	
1163			// Same computation as the text path (writeCheckpointSyncLines);
1164			// empty fields drop out via omitempty when nothing resolved.
1165			syncInfo := computeCheckpointSyncInfo(ctx, s)
1166			result.CheckpointPushDisabled = syncInfo.PushDisabled
1167			result.CheckpointSyncRemote = syncInfo.Remote
1168			result.CheckpointSyncRemoteSource = syncInfo.Source
1169			result.CheckpointSyncError = syncInfo.Err
1170			result.CheckpointReadFallback = syncInfo.ReadFallback
1171			result.CheckpointReadSourceUnknown = syncInfo.ReadSourceUnknown
1172			result.UnpushedCheckpoints = syncInfo.Unpushed
1173			result.CheckpointRemoteIgnored = syncInfo.IgnoredRemote
1174			result.CheckpointRemoteIgnoredReason = syncInfo.IgnoredReason
1175	
1770	
1771		result := formatSettingsStatus("Project", s, sty)
