1963	func TestRunStatusJSON_CodexInvalidWorktreePrecedesDiscovery(t *testing.T) {
1964		if runtime.GOOS == windowsGOOS {
1965			t.Skip("directory symlinks require privileges on Windows")
1966		}
1967	
1968		for _, test := range []struct {
1969			name       string
1970			discovered string
1971		}{
1972			{name: "healthy discovered hooks", discovered: canonicalCodexHooksJSON()},
1973			{name: "invalid discovered hooks", discovered: "{"},
1974		} {
1975			t.Run(test.name, func(t *testing.T) {
1976				tmp, repoRoot, linkedRoot := setupLinkedRepoForDoctorTest(t)
1977				writeCodexHooksForDiagnosticTest(t, repoRoot, test.discovered)
1978				if err := os.Symlink(filepath.Join(repoRoot, ".codex"), filepath.Join(linkedRoot, ".codex")); err != nil {
1979					t.Fatalf("create redirected project layer: %v", err)
1980				}
1981				t.Chdir(linkedRoot)
1982				t.Setenv("CODEX_HOME", filepath.Join(tmp, "codex-home"))
1983				writeSettings(t, testSettingsEnabled)
1984	
