1986				if err := runStatus(context.Background(), &stdout, false, true); err != nil {
1987					t.Fatalf("runStatus() error = %v", err)
1988				}
1989				var result statusJSON
1990				if err := json.Unmarshal(stdout.Bytes(), &result); err != nil {
1991					t.Fatalf("json.Unmarshal() error = %v", err)
1992				}
