func TestInstallHooks_RemovesStaleDenyRule(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	writeSettingsFile(t, tempDir, `{
  "permissions": {
    "deny": ["`+agentpkg.MetadataDenyRule+`"]
  }
}`)

	a := &ClaudeCodeAgent{}
	if _, err := a.InstallHooks(context.Background(), false); err != nil {
