func TestInstallHooks_DropsEmptyDenyArray(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	writeSettingsFile(t, tempDir, `{
  "permissions": {
    "deny": ["`+agentpkg.MetadataDenyRule+`"]
