		t.Fatalf("runStatus() error = %v", err)
	}
	for _, want := range []string{
		"○ not set up",
		"Claude Code worktree setup: INCOMPLETE",
		"Entire settings, Claude Code hooks",
		"entire enable --agent claude-code",
